<script setup lang="ts">
const props = withDefaults(
  defineProps<{
    points?: number | string
    maxPoints?: number
  }>(),
  {
    points: 30,
    maxPoints: 30
  }
)

// IDs entsprechen den Illustrator-Ebenennamen im SVG; die Zahl im Namen
// ist der Plant-Points-Schwellenwert, ab dem das Element erscheint.
const thresholds: Record<string, number> = {
  '1-Trauben': 1,
  '2-Erbse': 2,
  '3-Blaubeere': 3,
  '4-Erbse': 4,
  '5-Apfel': 5,
  '6-Erbse': 6,
  '8_Cashew': 8,
  '10-Blatt': 10,
  '12-Brokkoli': 12,
  '15-Möhre': 15,
  '18-Erdnuss': 18,
  '20-Paprika': 20,
  '21-Blatt': 21,
  '23-Blatt': 23,
  '25-Birne': 25,
  '27-Erbse': 27,
  '28-Erbse': 28,
  '29-Erbse': 29,
  '30-Blaetter': 30
}

const currentPoints = computed(() => Math.min(Number(props.points) || 0, props.maxPoints))

// Reihenfolge, in der die Elemente aufsteigend nach Schwellenwert erscheinen.
const orderedIds = Object.keys(thresholds).sort((a, b) => thresholds[a] - thresholds[b])

function isVisible(id: string) {
  return hasMounted.value && currentPoints.value >= thresholds[id]
}

function revealDelay(id: string) {
  return `${orderedIds.indexOf(id) * 60}ms`
}

// Erst nach dem ersten Paint auf sichtbar schalten, damit der Browser den
// "unsichtbar"-Zustand rendert und die Transition beim Laden abspielt -
// so füllt sich das Glas nacheinander statt alles auf einmal zu zeigen.
const hasMounted = ref(false)
onMounted(() => {
  requestAnimationFrame(() => {
    hasMounted.value = true
  })
})
</script>

